#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <stdexcept>

// Function to parse a comma-separated list of signed integers
std::vector<int> parseCommaSeparatedIntegers(const std::string& input) {
    std::vector<int> result;
    std::istringstream iss(input);
    std::string token;

    // Skip leading whitespace
    iss.ignore(std::numeric_limits<std::streamsize>::max(), ' ');

    while (std::getline(iss, token, ',')) {
        // Trim leading and trailing whitespace
        size_t start = token.find_first_not_of(" \t");
        size_t end = token.find_last_not_of(" \t");
        if (start == std::string::npos || end == std::string::npos) {
            continue; // Skip empty fields
        }

        std::string trimmedToken = token.substr(start, end - start + 1);
        try {
            int value = std::stoi(trimmedToken);
            result.push_back(value);
        } catch (const std::invalid_argument& e) {
            // Handle invalid integer conversion
            std::cerr << "Invalid integer: " << trimmedToken << std::endl;
            continue;
        } catch (const std::out_of_range& e) {
            // Handle integer out of range
            std::cerr << "Integer out of range: " << trimmedToken << std::endl;
            continue;
        }
    }

    return result;
}

